import { Server as SocketIOServer, Socket } from 'socket.io';
import { MultiplayerRoom, MultiplayerPlayer, MultiplayerGameAction, ChatMessage } from '../src/types/multiplayer';
import { TacticalMap, PlacedCharacter } from '../src/types/map';

export function setupMultiplayerSocket(httpServer: any) {
  const io = new SocketIOServer(httpServer, {
    cors: {
      origin: '*',
      methods: ['GET', 'POST'],
    },
    pingInterval: 10000,
    pingTimeout: 5000,
  });

  const rooms = new Map<string, MultiplayerRoom>();
  const matchmakingQueue: { socketId: string; player: MultiplayerPlayer; timestamp: number }[] = [];
  const socketMetadata = new Map<string, { userId: string; userName: string; roomId?: string }>();

  const MAIN_ROOM_ID = 'main_arena_room';

  const ensureMainRoom = (): MultiplayerRoom => {
    let mainRoom = rooms.get(MAIN_ROOM_ID);
    if (!mainRoom) {
      mainRoom = {
        id: MAIN_ROOM_ID,
        name: 'Главная Арена (Сетевая комната)',
        status: 'waiting',
        host: null,
        guest: null,
        spectator: null,
        spectators: [],
        creatorId: 'admin_server',
        creatorName: 'Сервер',
        mapId: 'docks_ruins_50x50',
        mapName: 'Портовые Руины (50×50)',
        turnNumber: 1,
        roundNumber: 1,
        createdAt: Date.now(),
      };
      rooms.set(MAIN_ROOM_ID, mainRoom);
    }
    return mainRoom;
  };

  // Pre-seed the primary room immediately
  ensureMainRoom();

  // Helper to build list of rooms for lobby
  const getEnrichedRoomsList = (): MultiplayerRoom[] => {
    ensureMainRoom();
    const list: MultiplayerRoom[] = [];
    const now = Date.now();

    for (const [id, room] of rooms.entries()) {
      // Auto-cleanup stale waiting rooms older than 30 minutes (never delete MAIN_ROOM_ID)
      if (id !== MAIN_ROOM_ID && room.status === 'waiting' && now - room.createdAt > 30 * 60 * 1000) {
        rooms.delete(id);
        continue;
      }

      const socketRoom = io.sockets.adapter.rooms.get(id);
      const onlineCount = socketRoom ? socketRoom.size : 0;

      list.push({
        ...room,
        onlineCount,
      });
    }

    return list.sort((a, b) => (a.id === MAIN_ROOM_ID ? -1 : b.id === MAIN_ROOM_ID ? 1 : b.createdAt - a.createdAt));
  };

  const broadcastRoomsList = () => {
    io.emit('rooms_list', getEnrichedRoomsList());
  };

  io.on('connection', (socket: Socket) => {
    // 1. Initial list request
    socket.on('get_rooms_list', () => {
      socket.emit('rooms_list', getEnrichedRoomsList());
    });

    // 2. Create room
    socket.on('create_room', (data: { roomName: string; host: MultiplayerPlayer; initialMap?: TacticalMap; asSpectator?: boolean }) => {
      try {
        const roomId = 'room-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 6);
        const creatorPlayer: MultiplayerPlayer = {
          ...data.host,
          selectedCharacters: Array.isArray(data.host.selectedCharacters) ? data.host.selectedCharacters.slice(0, 2) : [],
          isReady: false,
          connected: true,
        };

        const isCreatingAsSpectator = data.asSpectator || creatorPlayer.role === 'admin';

        const newRoom: MultiplayerRoom = {
          id: roomId,
          name: data.roomName?.trim() || `Кампания ${creatorPlayer.name}`,
          status: 'waiting',
          host: isCreatingAsSpectator ? null : creatorPlayer,
          guest: null,
          spectator: isCreatingAsSpectator ? creatorPlayer : null,
          spectators: isCreatingAsSpectator ? [creatorPlayer] : [],
          creatorId: creatorPlayer.id,
          creatorName: creatorPlayer.name,
          mapId: data.initialMap?.id || 'default_tactical_arena',
          mapName: data.initialMap?.name || 'Тактическая Арена',
          mapData: data.initialMap || undefined,
          turnNumber: 1,
          roundNumber: 1,
          createdAt: Date.now(),
        };

        rooms.set(roomId, newRoom);
        socketMetadata.set(socket.id, { userId: creatorPlayer.id, userName: creatorPlayer.name, roomId });
        socket.join(roomId);

        socket.emit('room_created', newRoom);
        socket.emit('room_updated', newRoom);
        broadcastRoomsList();
      } catch (err: any) {
        console.error('Error in create_room:', err);
        socket.emit('room_error', { message: 'Ошибка создания комнаты: ' + (err.message || 'Неизвестная ошибка') });
      }
    });

    // 3. Join room (or claim a specific slot)
    socket.on('join_room', (data: { roomId: string; guest: MultiplayerPlayer; targetSlot?: 'host' | 'guest' }) => {
      try {
        const room = rooms.get(data.roomId) || (data.roomId === MAIN_ROOM_ID ? ensureMainRoom() : undefined);
        if (!room) {
          return socket.emit('room_error', { message: 'Комната не найдена или была удалена' });
        }

        const userIdStr = String(data.guest.id);

        if (room.status === 'in_game' && 
            String(room.host?.id) !== userIdStr && 
            String(room.guest?.id) !== userIdStr && 
            String(room.spectator?.id) !== userIdStr
        ) {
          return socket.emit('room_error', { message: 'В этой комнате уже идёт матч' });
        }

        // Check if reconnecting/already in host slot
        if (room.host && String(room.host.id) === userIdStr) {
          room.host.connected = true;
          if (data.guest.name) room.host.name = data.guest.name;
          if (data.guest.avatarUrl) room.host.avatarUrl = data.guest.avatarUrl;
          if (Array.isArray(data.guest.selectedCharacters) && data.guest.selectedCharacters.length > 0) {
            room.host.selectedCharacters = data.guest.selectedCharacters.slice(0, 2);
          }
          socketMetadata.set(socket.id, { userId: userIdStr, userName: data.guest.name, roomId: data.roomId });
          socket.join(data.roomId);
          socket.emit('room_joined', room);
          io.to(data.roomId).emit('room_updated', room);
          broadcastRoomsList();
          return;
        }

        // Check if reconnecting/already in guest slot
        if (room.guest && String(room.guest.id) === userIdStr) {
          room.guest.connected = true;
          if (data.guest.name) room.guest.name = data.guest.name;
          if (data.guest.avatarUrl) room.guest.avatarUrl = data.guest.avatarUrl;
          if (Array.isArray(data.guest.selectedCharacters) && data.guest.selectedCharacters.length > 0) {
            room.guest.selectedCharacters = data.guest.selectedCharacters.slice(0, 2);
          }
          socketMetadata.set(socket.id, { userId: userIdStr, userName: data.guest.name, roomId: data.roomId });
          socket.join(data.roomId);
          socket.emit('room_joined', room);
          io.to(data.roomId).emit('room_updated', room);
          broadcastRoomsList();
          return;
        }

        const joiningPlayer: MultiplayerPlayer = {
          ...data.guest,
          id: userIdStr,
          selectedCharacters: Array.isArray(data.guest.selectedCharacters) ? data.guest.selectedCharacters.slice(0, 2) : [],
          isReady: false,
          connected: true,
        };

        // If explicit slot requested: HOST (Slot 1)
        if (data.targetSlot === 'host') {
          if (!room.host || String(room.host.id) === userIdStr) {
            if (room.guest && String(room.guest.id) === userIdStr) {
              room.guest = null;
            }
            if (room.spectators) {
              room.spectators = room.spectators.filter((s) => String(s.id) !== userIdStr);
            }
            if (room.spectator && String(room.spectator.id) === userIdStr) {
              room.spectator = null;
            }

            room.host = joiningPlayer;
            if (room.guest) room.status = 'ready'; else room.status = 'waiting';
            socketMetadata.set(socket.id, { userId: userIdStr, userName: joiningPlayer.name, roomId: data.roomId });
            socket.join(data.roomId);
            socket.emit('room_joined', room);
            io.to(data.roomId).emit('room_updated', room);
            broadcastRoomsList();
            return;
          } else {
            return socket.emit('room_error', { message: 'Слот Игрок 1 уже занят' });
          }
        }

        // If explicit slot requested: GUEST (Slot 2)
        if (data.targetSlot === 'guest') {
          if (!room.guest || String(room.guest.id) === userIdStr) {
            if (room.host && String(room.host.id) === userIdStr) {
              room.host = null;
            }
            if (room.spectators) {
              room.spectators = room.spectators.filter((s) => String(s.id) !== userIdStr);
            }
            if (room.spectator && String(room.spectator.id) === userIdStr) {
              room.spectator = null;
            }

            room.guest = joiningPlayer;
            if (room.host) room.status = 'ready'; else room.status = 'waiting';
            socketMetadata.set(socket.id, { userId: userIdStr, userName: joiningPlayer.name, roomId: data.roomId });
            socket.join(data.roomId);
            socket.emit('room_joined', room);
            io.to(data.roomId).emit('room_updated', room);
            broadcastRoomsList();
            return;
          } else {
            return socket.emit('room_error', { message: 'Слот Игрок 2 уже занят' });
          }
        }

        // Presence / Viewer mode (when opening room modal without targetSlot):
        if (!room.spectators) room.spectators = [];
        if (!room.spectators.some((s) => String(s.id) === userIdStr)) {
          room.spectators.push(joiningPlayer);
        }
        socketMetadata.set(socket.id, { userId: userIdStr, userName: joiningPlayer.name, roomId: data.roomId });
        socket.join(data.roomId);
        socket.emit('room_joined', room);
        io.to(data.roomId).emit('room_updated', room);
        broadcastRoomsList();
      } catch (err: any) {
        console.error('Error in join_room:', err);
        socket.emit('room_error', { message: 'Ошибка присоединения к комнате' });
      }
    });

    // 3a. Release player slot without leaving room
    socket.on('release_player_slot', (data: { roomId: string; userId: string }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;
      const userIdStr = String(data.userId);

      if (room.host && String(room.host.id) === userIdStr) {
        room.host = null;
        if (room.status === 'ready') room.status = 'waiting';
      }
      if (room.guest && String(room.guest.id) === userIdStr) {
        room.guest = null;
        if (room.status === 'ready') room.status = 'waiting';
      }

      io.to(data.roomId).emit('room_updated', room);
      broadcastRoomsList();
    });

    // 3b. Join as Spectator (Observer / GM slot - does not occupy player slot)
    socket.on('join_as_spectator', (data: { roomId: string; spectator: MultiplayerPlayer }) => {
      try {
        const room = rooms.get(data.roomId);
        if (!room) {
          return socket.emit('room_error', { message: 'Комната не найдена' });
        }

        const spectatorPlayer: MultiplayerPlayer = {
          ...data.spectator,
          selectedCharacters: [],
          isReady: true,
          connected: true,
        };

        const specId = String(spectatorPlayer.id);

        // If spectator was in host (Player 1) slot, FREE UP Player 1 slot!
        if (room.host && String(room.host.id) === specId) {
          room.host = null;
          if (room.status === 'ready') room.status = 'waiting';
        }

        // If spectator was in guest (Player 2) slot, FREE UP Player 2 slot!
        if (room.guest && String(room.guest.id) === specId) {
          room.guest = null;
          if (room.status === 'ready') room.status = 'waiting';
        }

        room.spectator = spectatorPlayer;
        if (!room.spectators) room.spectators = [];
        room.spectators = room.spectators.filter((s) => String(s.id) !== specId);
        room.spectators.push(spectatorPlayer);

        socketMetadata.set(socket.id, { userId: spectatorPlayer.id, userName: spectatorPlayer.name, roomId: data.roomId });
        socket.join(data.roomId);

        socket.emit('room_joined', room);
        io.to(data.roomId).emit('room_updated', room);
        broadcastRoomsList();
      } catch (err: any) {
        console.error('Error in join_as_spectator:', err);
        socket.emit('room_error', { message: 'Ошибка входа в слот наблюдателя' });
      }
    });

    // 3c. Leave spectator slot
    socket.on('leave_spectator_slot', (data: { roomId: string; userId: string }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      if (room.spectator && room.spectator.id === data.userId) {
        room.spectator = null;
      }
      if (room.spectators) {
        room.spectators = room.spectators.filter((s) => s.id !== data.userId);
      }

      io.to(data.roomId).emit('room_updated', room);
      broadcastRoomsList();
    });

    // 4. Select characters (each player picks up to 2 characters from their pool)
    socket.on('select_characters', (data: { roomId: string; playerId: string; characters: any[] }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      const chosen = Array.isArray(data.characters) ? data.characters.slice(0, 2) : [];

      if (room.host && room.host.id === data.playerId) {
        room.host.selectedCharacters = chosen;
      } else if (room.guest && room.guest.id === data.playerId) {
        room.guest.selectedCharacters = chosen;
      }

      io.to(data.roomId).emit('room_updated', room);
    });

    // 5. Toggle ready status
    socket.on('set_ready', (data: { roomId: string; playerId: string; isReady: boolean }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      if (room.host && room.host.id === data.playerId) {
        room.host.isReady = data.isReady;
      } else if (room.guest && room.guest.id === data.playerId) {
        room.guest.isReady = data.isReady;
      }

      io.to(data.roomId).emit('room_updated', room);
    });

    // 6. Start match / Spawn heroes on map
    socket.on('start_match', (data: { roomId: string; customMapData?: TacticalMap }) => {
      const room = rooms.get(data.roomId);
      if (!room) {
        return socket.emit('room_error', { message: 'Комната не найдена' });
      }

      const hostSelected = room.host?.selectedCharacters || [];
      const guestSelected = room.guest?.selectedCharacters || [];

      if (hostSelected.length === 0 && guestSelected.length === 0) {
        return socket.emit('room_error', { message: 'Выберите хотя бы 1-2 персонажа для игры' });
      }

      const baseMap: TacticalMap = data.customMapData || room.mapData || {
        id: 'arena_pvp_50x50',
        name: 'Тактическая PvP Арена',
        width: 50,
        height: 50,
        defaultTile: 'stone_ruins',
        tiles: {},
        obstacles: {},
        characters: [],
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };

      // Spawn Host's characters on Cooperative Spawn Area 1
      const hostSpawnedChars: PlacedCharacter[] = room.host ? room.host.selectedCharacters.map((c, idx) => {
        const spawnX = 14 + idx * 2;
        const spawnY = 24 + (idx % 2) * 2;
        return {
          id: `hero_host_${room.host!.id}_${c.id}_${idx}`,
          characterId: c.id,
          name: c.name,
          avatarUrl: c.avatarUrl || c.imageUrl,
          spriteUrl: (c as any).spriteUrl,
          characterFolder: c.characterFolder,
          stars: c.stars || 3,
          rarity: c.rarity || 'Редкий',
          role: c.role || 'Воин',
          faction: 'player',
          x: spawnX,
          y: spawnY,
          originX: spawnX,
          originY: spawnY,
          facing: 'right',
          currentHp: c.stats?.hp || 120,
          maxHp: c.stats?.hp || 120,
          currentMana: c.stats?.mana || 60,
          maxMana: c.stats?.mana || 60,
          currentAp: c.stats?.ap ?? 3,
          maxAp: c.stats?.ap ?? 3,
          currentMpPoints: c.stats?.speed ?? 5,
          maxMpPoints: c.stats?.speed ?? 5,
          speed: c.stats?.speed ?? 5,
          level: (c as any).level || 1,
          stats: c.stats,
          skills: c.skills || [],
          equippedEquipment: c.equippedEquipment,
          inventory: c.inventory || [],
          ownerId: room.host!.id,
          ownerName: room.host!.name,
          ownerPlayerNumber: 1,
        };
      }) : [];

      // Spawn Guest's characters on Cooperative Spawn Area 2
      const guestSpawnedChars: PlacedCharacter[] = room.guest ? room.guest.selectedCharacters.map((c, idx) => {
        const spawnX = 18 + idx * 2;
        const spawnY = 24 + (idx % 2) * 2;
        return {
          id: `hero_guest_${room.guest!.id}_${c.id}_${idx}`,
          characterId: c.id,
          name: c.name,
          avatarUrl: c.avatarUrl || c.imageUrl,
          spriteUrl: (c as any).spriteUrl,
          characterFolder: c.characterFolder,
          stars: c.stars || 3,
          rarity: c.rarity || 'Редкий',
          role: c.role || 'Воин',
          faction: 'player',
          x: spawnX,
          y: spawnY,
          originX: spawnX,
          originY: spawnY,
          facing: 'right',
          currentHp: c.stats?.hp || 120,
          maxHp: c.stats?.hp || 120,
          currentMana: c.stats?.mana || 60,
          maxMana: c.stats?.mana || 60,
          currentAp: c.stats?.ap ?? 3,
          maxAp: c.stats?.ap ?? 3,
          currentMpPoints: c.stats?.speed ?? 5,
          maxMpPoints: c.stats?.speed ?? 5,
          speed: c.stats?.speed ?? 5,
          level: (c as any).level || 1,
          stats: c.stats,
          skills: c.skills || [],
          equippedEquipment: c.equippedEquipment,
          inventory: c.inventory || [],
          ownerId: room.guest!.id,
          ownerName: room.guest!.name,
          ownerPlayerNumber: 2,
        };
      }) : [];

      const otherEntities = (baseMap.characters || []).filter(
        (c) => c.entityKind === 'mob' || c.entityKind === 'npc'
      );

      const finalMapData: TacticalMap = {
        ...baseMap,
        characters: [...hostSpawnedChars, ...guestSpawnedChars, ...otherEntities],
        updatedAt: Date.now(),
      };

      room.status = 'in_game';
      room.mapData = finalMapData;
      room.currentTurnCharacterId = hostSpawnedChars[0]?.id || guestSpawnedChars[0]?.id;
      room.activePlayerId = room.host?.id || room.guest?.id || room.spectator?.id;
      room.turnNumber = 1;
      room.roundNumber = 1;
      room.lastAction = {
        type: 'spawn',
        playerId: room.host?.id || room.spectator?.id || 'system',
        playerName: room.host?.name || room.spectator?.name || 'ГМ',
        timestamp: Date.now(),
        message: 'Матч начался! Герои заспавнены на арене.',
      };

      io.to(data.roomId).emit('match_started', { room, mapData: finalMapData });
      io.to(data.roomId).emit('room_updated', room);
      io.to(data.roomId).emit('game_sync', {
        room,
        mapData: finalMapData,
        lastAction: room.lastAction,
      });
      broadcastRoomsList();
    });

    // 7. Real-time Game Sync & Action Broadcasting (Zero-Lag Optimistic Updates)
    socket.on('update_game_state', (data: {
      roomId: string;
      action?: MultiplayerGameAction;
      mapData?: TacticalMap;
      currentTurnCharacterId?: string;
      activePlayerId?: string;
      winnerPlayerId?: string;
      winnerPlayerName?: string;
    }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      if (data.mapData) {
        room.mapData = {
          ...room.mapData,
          ...data.mapData,
          characters: data.mapData.characters || room.mapData?.characters || [],
          updatedAt: Date.now(),
        };
      }

      if (data.action) {
        room.lastAction = data.action;
      }

      if (data.currentTurnCharacterId !== undefined) {
        room.currentTurnCharacterId = data.currentTurnCharacterId;
      }

      if (data.activePlayerId !== undefined) {
        room.activePlayerId = data.activePlayerId;
      }

      if (data.winnerPlayerId) {
        room.status = 'finished';
        room.winnerPlayerId = data.winnerPlayerId;
        room.winnerPlayerName = data.winnerPlayerName;
      }

      // Broadcast to everyone in the room (including sender or excluding based on needs)
      io.to(data.roomId).emit('game_sync', {
        room,
        mapData: room.mapData,
        lastAction: data.action,
        currentTurnCharacterId: room.currentTurnCharacterId,
        activePlayerId: room.activePlayerId,
        status: room.status,
        winnerPlayerId: room.winnerPlayerId,
      });
    });

    // 8. In-room Chat
    socket.on('send_chat', (data: { roomId: string; message: ChatMessage }) => {
      io.to(data.roomId).emit('chat_received', data.message);
    });

    // 9. Leave Room
    socket.on('leave_room', (data: { roomId: string; playerId: string }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      socket.leave(data.roomId);
      socketMetadata.delete(socket.id);

      if (room.host && room.host.id === data.playerId) {
        // Host left
        if (room.status === 'in_game') {
          // Surrender in game
          room.status = 'finished';
          room.winnerPlayerId = room.guest?.id;
          room.winnerPlayerName = room.guest?.name;
          io.to(data.roomId).emit('opponent_surrendered', { winnerId: room.guest?.id, message: 'Хост покинул матч' });
        } else {
          room.host = null;
          room.status = 'waiting';
          io.to(data.roomId).emit('room_updated', room);
        }
      } else if (room.guest && room.guest.id === data.playerId) {
        // Guest left
        if (room.status === 'in_game') {
          room.status = 'finished';
          room.winnerPlayerId = room.host?.id;
          room.winnerPlayerName = room.host?.name;
          io.to(data.roomId).emit('opponent_surrendered', { winnerId: room.host?.id, message: 'Оппонент покинул матч' });
        } else {
          room.guest = null;
          room.status = 'waiting';
          io.to(data.roomId).emit('room_updated', room);
        }
      } else if (room.spectator && room.spectator.id === data.playerId) {
        room.spectator = null;
        if (room.spectators) room.spectators = room.spectators.filter((s) => s.id !== data.playerId);
        io.to(data.roomId).emit('room_updated', room);
      }

      // If room is empty of everyone, delete room (except MAIN_ROOM_ID which is permanent)
      if (!room.host && !room.guest && !room.spectator && (!room.spectators || room.spectators.length === 0)) {
        if (data.roomId !== MAIN_ROOM_ID) {
          rooms.delete(data.roomId);
          io.to(data.roomId).emit('room_closed', { message: 'Комната закрыта' });
        } else {
          room.status = 'waiting';
          io.to(data.roomId).emit('room_updated', room);
        }
      }

      broadcastRoomsList();
    });

    // 9a. Admin: Reset Room to Waiting State
    socket.on('admin_reset_room', (data: { roomId: string }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      room.status = 'waiting';
      room.currentTurnCharacterId = undefined;
      room.activePlayerId = undefined;
      room.winnerPlayerId = undefined;
      room.winnerPlayerName = undefined;
      room.turnNumber = 1;
      room.roundNumber = 1;
      if (room.host) room.host.isReady = false;
      if (room.guest) room.guest.isReady = false;

      io.to(data.roomId).emit('room_updated', room);
      broadcastRoomsList();
    });

    // 9b. Admin: Kick / Clear a player slot
    socket.on('admin_kick_slot', (data: { roomId: string; slot: 'host' | 'guest' }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      if (data.slot === 'host') {
        room.host = null;
      } else if (data.slot === 'guest') {
        room.guest = null;
      }

      if (room.status !== 'in_game') {
        room.status = 'waiting';
      }

      io.to(data.roomId).emit('room_updated', room);
      broadcastRoomsList();
    });

    // 9c. Admin: Change Map for the room
    socket.on('admin_change_map', (data: { roomId: string; mapData: TacticalMap }) => {
      const room = rooms.get(data.roomId);
      if (!room) return;

      room.mapData = data.mapData;
      room.mapId = data.mapData.id;
      room.mapName = data.mapData.name;

      io.to(data.roomId).emit('room_updated', room);
      broadcastRoomsList();
    });

    // 10. Matchmaking Queue
    socket.on('join_matchmaking', (player: MultiplayerPlayer) => {
      // Remove existing entry
      const existingIdx = matchmakingQueue.findIndex((p) => p.player.id === player.id || p.socketId === socket.id);
      if (existingIdx >= 0) {
        matchmakingQueue.splice(existingIdx, 1);
      }

      matchmakingQueue.push({ socketId: socket.id, player, timestamp: Date.now() });

      // If at least 2 players are in queue, pair them
      if (matchmakingQueue.length >= 2) {
        const p1 = matchmakingQueue.shift()!;
        const p2 = matchmakingQueue.shift()!;

        const roomId = 'match-' + Date.now().toString(36);
        const newRoom: MultiplayerRoom = {
          id: roomId,
          name: `Быстрый матч: ${p1.player.name} vs ${p2.player.name}`,
          status: 'ready',
          host: {
            ...p1.player,
            selectedCharacters: p1.player.selectedCharacters.slice(0, 2),
            isReady: false,
            connected: true,
          },
          guest: {
            ...p2.player,
            selectedCharacters: p2.player.selectedCharacters.slice(0, 2),
            isReady: false,
            connected: true,
          },
          mapId: 'arena_pvp_50x50',
          mapName: 'Тактическая PvP Арена',
          turnNumber: 1,
          roundNumber: 1,
          createdAt: Date.now(),
        };

        rooms.set(roomId, newRoom);

        const s1 = io.sockets.sockets.get(p1.socketId);
        const s2 = io.sockets.sockets.get(p2.socketId);

        if (s1) {
          s1.join(roomId);
          socketMetadata.set(p1.socketId, { userId: p1.player.id, userName: p1.player.name, roomId });
          s1.emit('match_found', newRoom);
        }
        if (s2) {
          s2.join(roomId);
          socketMetadata.set(p2.socketId, { userId: p2.player.id, userName: p2.player.name, roomId });
          s2.emit('match_found', newRoom);
        }

        broadcastRoomsList();
      }
    });

    socket.on('leave_matchmaking', () => {
      const idx = matchmakingQueue.findIndex((p) => p.socketId === socket.id);
      if (idx >= 0) {
        matchmakingQueue.splice(idx, 1);
      }
    });

    // 11. Disconnect handler
    socket.on('disconnect', () => {
      const qIdx = matchmakingQueue.findIndex((p) => p.socketId === socket.id);
      if (qIdx >= 0) matchmakingQueue.splice(qIdx, 1);

      const meta = socketMetadata.get(socket.id);
      if (meta && meta.roomId) {
        const room = rooms.get(meta.roomId);
        if (room) {
          const uId = String(meta.userId);
          if (room.host && String(room.host.id) === uId) {
            room.host.connected = false;
          } else if (room.guest && String(room.guest.id) === uId) {
            room.guest.connected = false;
          }
          io.to(meta.roomId).emit('room_updated', room);
        }
      }

      socketMetadata.delete(socket.id);
      broadcastRoomsList();
    });
  });

  return io;
}
